        2. Save important findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve your notes and provide a comprehensive summary.
        Be thorough but concise. Use 2-4 searches to cover the topic well.
        """,
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = tools,
    ModelOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    noteService.Clear();
    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {input}"),
    };

    Console.WriteLine("\nResearching...\n");

    try
    {
        await foreach (var response in agent.InvokeStreamingAsync(messages, options))
        {
            if (response.Role == ChatRole.Assistant && !string.IsNullOrEmpty(response.Text))
            {
                Console.Write(response.Text);
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\nError: {ex.Message}");
    }

    Console.WriteLine("\n");
    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

/// <summary>
/// Simulated web search tool that uses a public search API or returns mock results.
/// Replace with a real search API (Bing, Google, Brave) for production use.
/// </summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  [🔍 Searching: \"{query}\"]");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await Http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            if (response.TryGetProperty("AbstractText", out var abstractText)
                && abstractText.GetString() is { Length: > 0 } text)
            {
                results.Add($"Summary: {text}");
            }

            if (response.TryGetProperty("RelatedTopics", out var topics)
                && topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var topicText)
                        && topicText.GetString() is { Length: > 0 } t)
                    {
                        results.Add($"- {t}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try a more specific search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>
/// Simple in-memory note-taking service for the research agent.
/// </summary>
class NoteService
{
    private readonly List<(string Title, string Content)> _notes = [];

    public void AddNote(string title, string content)
    {
        _notes.Add((title, content));
        Console.WriteLine($"  [📝 Note saved: \"{title}\"]");
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"Note {i + 1} - {n.Title}:\n{n.Content}"));
    }

    public void Clear() => _notes.Clear();
}

